import {esc,L,boardSVG,fmt} from './draw.mjs?v=c87ada8ce080';
import {GOLDEN} from './core.mjs?v=b7d4c6912114';
export function lessonExtras(m,phase,{lang,base}){
 if(!m.fullLesson)return '';const T=(zh,en)=>lang==='zh'?zh:en,tx=x=>esc(L(x,lang));
 if(phase==='before-notes')return `<section class="section" id="prerequisites"><span class="eyebrow">BEFORE YOU START</span><h2>${T('先备知识与本课模型','Prerequisites and the shared model')}</h2><p>${T('需要会读二维坐标、计算矩形面积，以及区分“贴边”和“内部重叠”。树、图和退火都不是本课前提。','You need coordinates, rectangle area, and the difference between contact and interior overlap. Trees, graphs, and annealing are not prerequisites.')}</p><p><a href="${base}lessons/02/">${T('回看：合法性','Review: legality')}</a> · <a href="${base}lessons/03/">${T('回看：包围盒与密度','Review: bounding boxes and density')}</a></p><figure class="lesson-figure"><svg viewBox="390 125 480 395" role="img" aria-label="${T('原始五模块布局，A与D贴边，包围盒9乘3','Baseline five-block layout: A touches D, bounding box nine by three')}">${boardSVG(GOLDEN,{bbox:true,focus:['A','D'],lang})}</svg><figcaption>${T('原始布局：A=(0,0,3,2)，D=(0,2,3,1)。只有 A 允许改变形状；所有坐标都取模块左下角。','Baseline: A=(0,0,3,2), D=(0,2,3,1). Only A may reshape; coordinates identify each block’s lower-left corner.')}</figcaption></figure></section>`;
 if(phase==='before-lab')return `<section class="section" id="worked-example"><span class="eyebrow">FOLLOW THE NUMBERS</span><h2>${T('把每一步，和检查结果对上','Match each move to its result')}</h2><p>${T('下面是讲解的端点状态。动画中的移动过程不自动视为合法的搬运路径；每次落定后重新检查。','These are the endpoint states in the explanation. Animated motion is not a certified collision-free transport path; each settled placement is checked again.')}</p><div class="table-scroll"><table><thead><tr><th>${T('步骤','Step')}</th><th>${T('本次动作','Change')}</th><th>${T('结果','Result')}</th><th>${T('包围盒','Bounding box')}</th></tr></thead><tbody>${m.worked.map(r=>`<tr><td>${tx(r.label)}</td><td>${tx(r.action)}</td><td>${r.legal?T('合法','Legal'):tx(r.reason)}</td><td>${fmt(r.width)}×${fmt(r.height)}=${fmt(r.area)}</td></tr>`).join('')}</tbody></table></div><p class="small">${T('27 → 36 → 27 → 24，分别对应原布局、合法但松散的修复、恢复原面积、真正压紧。','27 → 36 → 27 → 24 distinguishes baseline, a legal but loose repair, recovery to baseline area, and actual compaction.')}</p></section>`;
 if(phase==='before-quiz')return `<section class="section" id="guided-practice"><span class="eyebrow">PREDICT → TRY → EXPLAIN</span><h2>${T('四个练习，检查是否真的会了','Four exercises to test understanding')}</h2><ol class="guided-tasks"><li><strong>${T('筛形状','Filter shapes')}</strong><p>${T('列出面积6的整数形状，并用比例条件排除不允许的项。','List integer shapes of area 6 and reject those outside the ratio bounds.')}</p><details><summary>${T('查看解释','Show explanation')}</summary><p>${T('1×6、2×3、3×2、6×1中，只允许2×3、3×2。1/6小于0.5，6大于2。','Only 2×3 and 3×2 survive. The ratios 1/6 and 6 fall outside 0.5…2.')}</p></details></li><li><strong>${T('算出碰撞','Calculate the overlap')}</strong><p>${T('A=(0,0,2,3)，D=(0,2,3,1)。写出两个共同区间和重叠面积。','For A=(0,0,2,3) and D=(0,2,3,1), give the shared intervals and overlap area.')}</p><details><summary>${T('查看解释','Show explanation')}</summary><p>${T('横向0…2，纵向2…3，面积2。不是贴边，因为两个方向都有正长度。','Shared intervals are x=0…2 and y=2…3, giving area 2. Both overlap lengths are positive.')}</p></details></li><li><strong>${T('分两关完成重摆','Repack in two stages')}</strong><p>${T('先在上方实验修好布局，再尝试保持A=2×3、合法且包围盒不超过24。下面的按钮检查当前实验状态。','First repair the lab placement above. Then keep A=2×3 and target a legal box of area at most 24. The button checks your current lab state.')}</p><button id="compact-challenge-check" class="primary">${T('检查进阶目标','Check the advanced target')}</button><p id="compact-challenge-message" role="status"></p></li><li><strong>${T('迁移到面积8','Transfer to area 8')}</strong><p>${T('同样的比例范围下，面积8有哪些整数形状允许？端点是否应通过？','Which integer shapes of area 8 satisfy the same ratio limits? Are the endpoints included?')}</p><details><summary>${T('查看解释','Show explanation')}</summary><p>${T('2×4与4×2都通过，比例为0.5和2。3×3不通过，因为面积为9。','Both 2×4 and 4×2 pass at ratios 0.5 and 2. A 3×3 shape fails because its area is 9.')}</p></details></li></ol></section>`;
 if(phase==='before-resources')return `<section class="section" id="lesson-glossary"><span class="eyebrow">KEEP THE TERMS CONSISTENT</span><h2>${T('本课术语速查','Lesson vocabulary')}</h2><dl class="lesson-terms">${m.terms.map(t=>`<div><dt>${esc(lang==='zh'?t.zh:t.en)}</dt><dd>${tx(t.definition)}</dd></div>`).join('')}</dl></section>`;
 return '';
}
